class Solution {
public:
    int getLeastFrequentDigit(int n) {
        int cnt[10] = {0};
        if (n == 0) cnt[0] = 1;
        while (n > 0) { cnt[n % 10]++; n /= 10; }
        int best = -1, bc = INT_MAX;
        for (int d = 0; d < 10; d++) if (cnt[d] > 0 && cnt[d] < bc) { bc = cnt[d]; best = d; }
        return best;
    }
};

