var getLeastFrequentDigit = function(n) {
    const cnt = new Array(10).fill(0);
    if (n === 0) cnt[0] = 1;
    while (n > 0) { cnt[n % 10]++; n = Math.floor(n / 10); }
    let best = -1, bc = Infinity;
    for (let d = 0; d < 10; d++) if (cnt[d] > 0 && cnt[d] < bc) { bc = cnt[d]; best = d; }
    return best;
};
